#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
umask 077
NABDA_SETUP_ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
cd "$NABDA_SETUP_ROOT"
ENV_FILE="$NABDA_SETUP_ROOT/.env.deploy"
NABDA_WRANGLER="$NABDA_SETUP_ROOT/node_modules/wrangler/bin/wrangler.js"
NABDA_NETLIFY_VERSION=27.16.2

if ! command -v node >/dev/null 2>&1 || ! command -v python3 >/dev/null 2>&1; then
  printf 'Install Node.js 22.13+ and Python 3 before running this setup.\n' >&2
  exit 1
fi
node -e 'const [a,b] = process.versions.node.split(".").map(Number); if (a < 22 || (a === 22 && b < 13)) { process.stderr.write("Node.js 22.13+ is required.\n"); process.exit(1); }'
if [[ ! -f "$NABDA_WRANGLER" ]]; then
  printf 'Run npm ci in this project before starting setup.\n' >&2
  exit 1
fi

banner "Nabda: connect your hosting accounts"

stage "Cloudflare: sign in"
say "Use your own Cloudflare Free account. The browser will ask you to authorize Wrangler."
open_url "https://dash.cloudflare.com/"
step "Create a free account or sign in. No hosting purchase is needed for this setup."
pause "Press Enter to start Cloudflare's browser sign-in."
node "$NABDA_WRANGLER" login
step "In Workers & Pages, find or choose your workers.dev subdomain."
note "We use that subdomain for the API address in stage 4. No deployment happens yet."
pause

stage "Netlify: sign in and choose a project"
say "The CLI signs in through your browser; no access token is copied into this wizard."
open_url "https://app.netlify.com/"
pause "Press Enter to start Netlify's browser sign-in."
npx --yes "netlify-cli@$NABDA_NETLIFY_VERSION" login
if confirm "Use an existing Netlify project?"; then
  npx --yes "netlify-cli@$NABDA_NETLIFY_VERSION" link
else
  note "The next command creates an empty project in your selected account and links this folder."
  npx --yes "netlify-cli@$NABDA_NETLIFY_VERSION" sites:create
fi
step "Keep the project URL shown by Netlify; enter it in stage 4. Choose the Free plan."
pause

stage "Cloudflare D1: select the account database"
say "Use a NEW, empty D1 database for this independent installation."
note "This setup does not copy existing Sites users, keys, phone tokens or commands."
open_url "https://dash.cloudflare.com/"
ask NABDA_D1_DATABASE_NAME "Database name [nabda-api]:"
NABDA_D1_DATABASE_NAME="${NABDA_D1_DATABASE_NAME:-nabda-api}"
if [[ ! "$NABDA_D1_DATABASE_NAME" =~ ^[A-Za-z0-9][A-Za-z0-9_-]{0,62}$ ]]; then
  printf 'Invalid database name. Use letters, digits, underscores or hyphens.\n' >&2
  exit 1
fi
ask NABDA_D1_DATABASE_ID "Existing NEW database UUID (leave empty to create one):"
if [[ -z "$NABDA_D1_DATABASE_ID" ]]; then
  node "$NABDA_WRANGLER" d1 create "$NABDA_D1_DATABASE_NAME"
  ask NABDA_D1_DATABASE_ID "Paste the database_id UUID printed above:"
fi
write_env NABDA_D1_DATABASE_NAME "$NABDA_D1_DATABASE_NAME"
write_env NABDA_D1_DATABASE_ID "$NABDA_D1_DATABASE_ID"
pause

stage "Public addresses: website and API"
say "These values are public addresses, not secrets. Do not include paths or a trailing query."
ask NABDA_WORKER_NAME "Worker name [nabda-api]:"
NABDA_WORKER_NAME="${NABDA_WORKER_NAME:-nabda-api}"
step "API example: https://nabda-api.YOUR_WORKERS_SUBDOMAIN.workers.dev"
ask NABDA_API_ORIGIN "Your full HTTPS API origin:"
NABDA_API_ORIGIN="${NABDA_API_ORIGIN%/}"
step "Website: copy the https://PROJECT.netlify.app address from your Netlify project."
ask NABDA_WEBSITE_ORIGIN "Your full HTTPS website origin:"
NABDA_WEBSITE_ORIGIN="${NABDA_WEBSITE_ORIGIN%/}"
write_env NABDA_WORKER_NAME "$NABDA_WORKER_NAME"
write_env NABDA_API_ORIGIN "$NABDA_API_ORIGIN"
write_env NABDA_WEBSITE_ORIGIN "$NABDA_WEBSITE_ORIGIN"
pause

stage "GitHub: register Nabda sign-in"
say "Register an OAuth App owned by you. This is for account sign-in, not repository access."
open_url "https://github.com/settings/applications/new"
step "Application name: Nabda"
step "Homepage URL: $NABDA_WEBSITE_ORIGIN"
step "Authorization callback URL: $NABDA_API_ORIGIN/auth/github/callback"
step "Register the application and copy its public Client ID."
ask NABDA_GITHUB_CLIENT_ID "Public GitHub OAuth Client ID:"
write_env NABDA_GITHUB_CLIENT_ID "$NABDA_GITHUB_CLIENT_ID"
note "Keep the Client Secret private. Later, npm run secret:cloudflare will prompt for it directly."
note "Do not paste that secret into this wizard, Netlify, the public .env.deploy file or a chat."
pause

stage "Validate and build: no publication"
say "Validate the public settings and generate both independent deployment outputs."
node --input-type=module -e 'import {readDeploymentSettings} from "./scripts/cloudflare-config.mjs"; readDeploymentSettings(); console.log("Public configuration validated.");'
npm run build:independent
npm run check:cloudflare
say "Preparation is complete. Nothing has been deployed by this wizard."
step "Next: follow docs/DEPLOYMENT.md to apply the fresh database migrations, deploy the API,"
step "set its GitHub secret privately, and publish deploy-build/netlify."
note "Cloudflare and Netlify keep their own CLI login state outside the public export."
pause "Press Enter for the setup summary."
finish
say "Prepared: .env.deploy, wrangler.nabda.json, deploy-build/cloudflare-assets and deploy-build/netlify."
say "Next steps: docs/DEPLOYMENT.md. Keep the existing service running until sandbox cutover checks pass."
